float hash12(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

mat2 rot2d(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}

// Smoother noise implementation
float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    // Smooth interpolation
    f = f * f * (3.0 - 2.0 * f);

    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));

    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

// Smoother fbm
float fbm(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;

    for(int i = 0; i < 5; i++) {
        sum += amp * noise(p * freq);
        amp *= 0.5;
        freq *= 2.0;
        p = rot2d(0.4) * p;
    }
    return sum;
}

// More aggressive fbm for texture detail
float textureNoise(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;

    for(int i = 0; i < 3; i++) {
        sum += amp * abs(noise(p * freq) * 2.0 - 1.0); // More detailed
        amp *= 0.6;
        freq *= 3.0;
        p = rot2d(0.8) * p;
    }
    return sum;
}


// Pattern generation
float getPattern(vec2 uv, float time) {
    vec2 p = uv - 0.5;
    float angle = atan(p.y, p.x);
    float rad = length(p);

    // Base angular form
    float form = sin(angle * 4.0 + time) * 0.5 + 0.5;
    form *= smoothstep(0.5, 0.1, rad);

    // Add wave detail
    float wave = sin(rad * 20.0 - time * 2.0) * 0.5 + 0.5;
    wave *= smoothstep(0.4, 0.0, rad);

    return mix(form, wave, 0.5);
}

float getAudioIntensity(float freq) {
    float intensity = 0.0;
    for(int i = 0; i < 8; i++) {
        intensity += texture(iChannel0, vec2(freq + float(i) * 0.01, 0.0)).x;
    }
    return intensity / 8.0;
}

// More aggressive smoke noise
float smokeNoise(vec2 p) {
    float sum = 0.0;
    float amp = 0.5;
    float freq = 1.0;
    mat2 rot = rot2d(0.5);

    for(int i = 0; i < 4; i++) {
        sum += amp * noise(p * freq);
        amp *= 0.6;
        freq *= 2.5; // More frequency separation
        p = rot * p + sum * 0.5; // Feed noise back into position
    }
    return sum;
}

// Enhanced distortion with audio reactivity
vec2 audioDistort(vec2 uv, float time, float audioBoost) {
    vec2 p = uv - 0.5;
    float angle = atan(p.y, p.x);
    float rad = length(p);

    // Multiple layers of distortion
    float dist1 = smokeNoise(p * 2.0 + time * 0.2);
    float dist2 = smokeNoise(p * 4.0 - time * 0.3);

    // Add audio-reactive turbulence
    float turbulence = smokeNoise(p * 3.0 + dist1 * 2.0);
    turbulence *= audioBoost;

    return uv + vec2(
        cos(angle) * dist1 + dist2,
        sin(angle) * dist1 + turbulence
    ) * 0.1;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord/iResolution.xy;
    float time = iTime * 0.3;

    // Audio analysis
    float bassIntensity = getAudioIntensity(0.05) * 2.0;
    float midIntensity = getAudioIntensity(0.2) * 1.5;
    float highIntensity = getAudioIntensity(0.4);

    // Layer 1: Base with audio-reactive movement
    float baseNoise = smokeNoise(uv * (2.0 + bassIntensity) + time * 0.1);
    vec3 color = vec3(0.02, 0.03, 0.04);
    color += vec3(0.01, 0.02, 0.02) * baseNoise * (1.0 + bassIntensity);

    // Layer 2: Deep smoke with audio distortion
    vec2 smokeUV = audioDistort(uv, time, bassIntensity + midIntensity);
    float deepSmoke = smokeNoise(smokeUV * 3.0 - time * 0.2);
    deepSmoke *= 1.0 + midIntensity * 0.5;
    color = mix(color, vec3(0.04, 0.06, 0.05), deepSmoke * 0.5);

    // Layer 3: High-frequency reactive texture
    float textureDetail = smokeNoise(smokeUV * (5.0 + highIntensity * 2.0));
    color += vec3(0.02) * textureDetail * (1.0 + highIntensity);

    // Layer 4: Audio-reactive symmetrical pattern
    vec2 symUV = abs(smokeUV - 0.5) + 0.5;
    float pattern = getPattern(symUV, time);
    pattern *= 1.0 + (bassIntensity + midIntensity) * 0.5;

    // Layer 5: Dynamic glow based on audio
    float glow = 0.0;
    const int samples = 6;
    for(int i = 0; i < samples; i++) {
        float scale = 1.0 + float(i) * 0.05 * (1.0 + midIntensity * 0.5);
        vec2 glowUV = (symUV - 0.5) * scale + 0.5;
        glow += getPattern(glowUV, time) / float(samples);
    }

    // Layer 6: Pattern integration with smoke distortion
    vec3 brightColor = vec3(1.0, 1.0, 0.98);
    vec3 glowColor = vec3(0.7, 0.85, 0.8);

    // Additional smoke distortion for pattern breakup
    vec2 patternDistort = audioDistort(symUV, time + 10.0, midIntensity);
    float distortedPattern = pattern * smokeNoise(patternDistort * 4.0);

    // Blend with audio-reactive masks
    float patternMask = pattern * (1.0 - deepSmoke * (0.5 + bassIntensity * 0.3));
    color = mix(color, brightColor, patternMask);
    color += glowColor * glow * (0.4 + midIntensity * 0.3);

    // Layer 7: Audio-reactive fine detail
    float fineNoise = (noise(uv * (10.0 + highIntensity * 5.0) + time) - 0.5) * 0.03;
    color += fineNoise * (1.0 + highIntensity);

    // Layer 8: Additional turbulent distortion
    float turbulence = smokeNoise(patternDistort * 6.0 + time * 0.5) * bassIntensity;
    color = mix(color, brightColor, distortedPattern * turbulence * 0.3);

    // Final adjustments
    float vignette = smoothstep(1.2, 0.2, length(uv - 0.5));
    color *= vignette;
    color = pow(color, vec3(1.1 - bassIntensity * 0.2)); // Dynamic contrast

    fragColor = vec4(color, 1.0);
}
